class RiverTributaryJoinTest{public static void main(String[]a){int n=128;float[] h=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)h[z*n+x]=180-z*.7f+Math.abs(x-64)*.1f;var e=new EnvironmentMap(h.clone());e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];var flow=EnvironmentNodes.drainage(h,n,()->false);NaturalRivers.trace(e,h,flow,64*n+64,n,1024,62,.4375,3,Float.POSITIVE_INFINITY,1,83,()->false);var first=e.ribbons;NaturalRivers.trace(e,h,flow,20*n+64,n,1024,62,.4375,3,Float.POSITIVE_INFINITY,1,83,()->false);var last=e.ribbons.segments.get(e.ribbons.segments.size()-1).b();double best=Double.POSITIVE_INFINITY;for(var s:first.segments){double dx=s.b().x()-s.a().x(),dz=s.b().z()-s.a().z(),t=Math.max(0,Math.min(1,((last.x()-s.a().x())*dx+(last.z()-s.a().z())*dz)/Math.max(.001,dx*dx+dz*dz)));best=Math.min(best,Math.hypot(last.x()-s.a().x()-dx*t,last.z()-s.a().z()-dz*t));}if(best>.01||last.z()>600)throw new AssertionError("Tributary failed to join: distance="+best+" endpoint="+last);System.out.println("PASS: upstream tributary stops at and joins existing vector river, without duplicating its downstream path");}}
